  L.ex.forEach(e=>{const u=unlink(e[0]),r=/⟦([^⟧]+)⟧/.exec(u);if(!r)return;const ans=plain(r[1]),d=pick3(pool,ans);if(d.length<3)return;
    qs.push({s:plain(u.replace(r[0],'___')),k:e[1],ask:'빈칸에 들어갈 문형을 고르세요',o:[ans].concat(d),why:plain(e[0])})});
