const AF={i:[['neg','부정','~하지 않다','くない'],['past','과거','~했다','かった'],['pastneg','과거 부정','~하지 않았다','くなかった'],['te','て형','~하고, ~해서','くて'],['adv','부사형','~하게','く'],['nar','~해지다','~해지다','くなる'],['ba','가정형','~하면','ければ']],
 na:[['noun','명사 앞','~한 (명사를 꾸밈)','な'],['pred','서술','~하다 (보통체)','だ'],['neg','부정','~하지 않다','じゃない'],['past','과거','~했다','だった'],['pastneg','과거 부정','~하지 않았다','じゃなかった'],['te','て형','~하고, ~해서','で'],['adv','부사형','~하게','に'],['nar','~해지다','~해지다','になる'],['cond','가정','~하다면','なら']]};
const KEIGO={'行く':[['いらっしゃる','いらっしゃる'],['参る','まいる']],'来る':[['いらっしゃる','いらっしゃる'],['参る','まいる']],'いる':[['いらっしゃる','いらっしゃる'],['おる','おる']],'居る':[['いらっしゃる','いらっしゃる'],['おる','おる']],
 '言う':[['おっしゃる','おっしゃる'],['申す','もうす']],'食べる':[['召し上がる','めしあがる'],['いただく','いただく']],'飲む':[['召し上がる','めしあがる'],['いただく','いただく']],'見る':[['ご覧になる','ごらんになる'],['拝見する','はいけんする']],
 'する':[['なさる','なさる'],['いたす','いたす']],'為る':[['なさる','なさる'],['いたす','いたす']],'知る':[['ご存じだ','ごぞんじだ'],['存じる','ぞんじる']],'会う':[['お会いになる','おあいになる'],['お目にかかる','おめにかかる']],
 '聞く':[['お聞きになる','おききになる'],['伺う','うかがう']],'くれる':[['くださる','くださる'],null],'呉れる':[['くださる','くださる'],null],'もらう':[null,['いただく','いただく']],'貰う':[null,['いただく','いただく']],
 'あげる':[null,['差し上げる','さしあげる']],'上げる':[null,['差し上げる','さしあげる']],'寝る':[['お休みになる','おやすみになる'],null],'着る':[['お召しになる','おめしになる'],null]};
const GRPNAME={'5':'1그룹 동사','1':'2그룹 동사','s':'3그룹 동사 (する)','k':'3그룹 동사 (来る)','z':'ずる 동사','i':'い형용사','na':'な형용사'};
