/* report */
const RK=['뜻이 틀림','예문이 어색함','후리가나·읽기 틀림','연결된 카드가 틀림','한자 정보 틀림','기타'];
function reportTarget(key){const [k,id]=[key.slice(0,1),key.slice(2)];if(k==='w'){const w=byId(id);return w?w.jp+' ('+w.kana+')':id}if(k==='g'){const l=LESSONS.find(x=>x.id===id);return l?l.t:id}return id}
function vReport(s){return '<h2>오류 신고</h2><p class="muted">'+esc(reportTarget(s.key))+'</p><div class="panel"><span class="small muted">무엇이 문제인가요?</span><div class="chips">'+RK.map(k=>'<button class="chip'+(s.kind===k?' in':'')+'" data-a="rkind" data-v="'+k+'" aria-pressed="'+(s.kind===k)+'">'+k+'</button>').join('')+'</div>'+
  '<label class="search"><span class="small muted">자세한 내용 (선택)</span><textarea id="rtext" rows="3" placeholder="예: 예문의 何は なに로 읽어야 합니다"></textarea></label><button class="btn" data-a="rsend"'+(s.kind?'':' disabled')+'>신고 저장</button>'+
  '<p class="small muted">신고는 이 기기에 모입니다. 설정의 "오류 신고 목록"에서 한꺼번에 복사해 보내 주시면 고칩니다.</p></div>'}
function reportText(){return S.reports.map((r,i)=>(i+1)+'. ['+r.kind+'] '+reportTarget(r.key)+' <'+r.key+'>'+(r.text?' : '+r.text:'')).join('\n')}

/* settings */
function vSettings(){const vs=jaVoices(),seg=(a,list,cur)=>'<div class="seg">'+list.map(x=>'<button data-a="'+a+'" data-v="'+x[0]+'" aria-pressed="'+(String(cur)===String(x[0]))+'">'+x[1]+'</button>').join('')+'</div>';
  return '<h2>설정</h2>'+flash()+
  '<section class="stack"><h3>하루 목표</h3><div class="panel"><span class="small muted">새 단어 수</span>'+seg('goalnw',[[5,'5개'],[10,'10개'],[20,'20개'],[30,'30개']],S.set.nw)+'<span class="small muted">복습 최대 수</span>'+seg('goalrv',[[20,'20개'],[30,'30개'],[50,'50개'],[100,'100개']],S.set.rv)+'</div></section>'+
  '<section class="stack"><h3>화면</h3>'+displayHTML()+'</section>'+
  '<section class="stack"><h3>발음</h3><div class="panel">'+(!canSpeak?'<p class="muted">이 브라우저는 음성 읽기를 지원하지 않습니다.</p>':
    (vs.length?'<label class="search"><span class="small muted">일본어 음성</span><select id="voice"><option value="">기본 음성</option>'+vs.map(v=>'<option value="'+esc(v.name)+'"'+(S.set.voice===v.name?' selected':'')+'>'+esc(v.name)+'</option>').join('')+'</select></label>':'<p class="small muted">기기에 일본어 음성이 없으면 소리가 나지 않을 수 있습니다. 기기 설정에서 일본어 음성을 추가하세요.</p>')+
    '<span class="small muted">속도</span>'+seg('rate',[[.7,'느리게'],[.9,'보통'],[1.1,'빠르게']],S.set.rate)+'<button class="btn quiet" data-a="speak" data-v="こんにちは。一緒に日本語を勉強しましょう。">들어 보기</button>')+'</div></section>'+
  '<section class="stack"><h3>기기 간 동기화</h3><div class="panel"><p>'+esc(SY.msg||(window.STANDALONE?'이 버전은 자동 동기화를 지원하지 않습니다. 아래 백업 코드로 옮기세요.':'로그인한 Claude 계정으로 자동 동기화를 준비하는 중입니다.'))+'</p></div></section>'+
  '<section class="stack"><h3>오류 신고 목록</h3><div class="panel">'+(S.reports.length?'<p class="num">'+S.reports.length+'건 모였습니다.</p><textarea id="rout" class="bk" readonly rows="5">'+esc(reportText())+'</textarea><div class="row-btns"><button class="btn ghost" data-a="rcopy">목록 복사</button><button class="btn quiet" data-a="rclear">'+(V.rarm?'한 번 더 누르면 비웁니다':'목록 비우기')+'</button></div>':'<p class="muted">아직 신고한 내용이 없습니다. 카드 위쪽의 "신고"를 누르면 여기에 모입니다.</p>')+'</div></section>'+
  backupHTML().replace('<section class="stack"><h3>백업과 복구</h3><button','<section class="stack"><h3>백업과 복구</h3><button')+
  '<button class="btn quiet small" data-a="reset">'+(armed?'한 번 더 누르면 모든 기록이 지워집니다':'학습 기록 지우기')+'</button>'}

/* stats */
function streak(){let n=0;const d=new Date();const has=k=>{const L=S.log[k];return L&&((L.n||0)+(L.r||0)+(L.g||0))>0};
  const key=x=>x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');
  if(!has(key(d)))d.setDate(d.getDate()-1);while(has(key(d))){n++;d.setDate(d.getDate()-1)}return n}
function vStats(){const days=[];const d=new Date();d.setDate(d.getDate()-13);
  for(let i=0;i<14;i++){const k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'),L=S.log[k]||{};days.push({k,day:d.getDate(),n:L.n||0,r:L.r||0,g:L.g||0,ok:L.ok||0,ng:L.ng||0});d.setDate(d.getDate()+1)}
  const max=Math.max(1,...days.map(x=>x.n+x.r)),tok=days.slice(-7).reduce((a,x)=>a+x.ok,0),tng=days.slice(-7).reduce((a,x)=>a+x.ng,0);
  const tot=days.reduce((a,x)=>a+x.n+x.r,0),newT=days.reduce((a,x)=>a+x.n,0);
  const bars='<div class="chart" role="img" aria-label="최근 14일 학습량">'+days.map((x,i)=>'<div class="col'+(i===13?' now':'')+'" title="'+x.k+' 새 단어 '+x.n+', 복습 '+x.r+'"><span class="num v">'+((x.n+x.r)||'')+'</span><i style="height:'+((x.n+x.r)/max*100).toFixed(1)+'%"><b style="height:'+(x.n+x.r?x.n/(x.n+x.r)*100:0).toFixed(1)+'%"></b></i><span class="num d">'+x.day+'</span></div>').join('')+'</div>'+
    '<p class="small muted"><span class="key new"></span>새 단어 <span class="key rev"></span>복습 · 막대 위 숫자는 그날 푼 단어 수</p>';
  const lvRows=DB.ready?LV.map(n=>{const st=lvStat(n),t=DB.lv[n].length,gl=LESSONS.filter(l=>l.lv===n),gd=gl.filter(l=>!undone(l)).length;
    return '<div class="lvrow"><span class="lvg">N'+n+'</span><div class="grow"><div class="bar"><i style="width:'+(st.m/t*100).toFixed(1)+'%"></i></div><span class="small muted num">단어 '+fmt(st.m)+' / '+fmt(t)+' · 문법 '+gd+' / '+gl.length+'</span></div></div>'}).join(''):loading();
  const ex=S.exams.slice(-5).reverse();
  return '<h2>학습 통계</h2><div class="panel"><div class="stats"><div><b class="num">'+streak()+'일</b><span class="small muted">연속 학습</span></div><div><b class="num">'+fmt(tot)+'</b><span class="small muted">14일 학습량</span></div><div><b class="num">'+fmt(newT)+'</b><span class="small muted">14일 새 단어</span></div><div><b class="num">'+(tok+tng?Math.round(tok/(tok+tng)*100)+'%':'–')+'</b><span class="small muted">7일 정답률</span></div></div></div>'+
  '<section class="stack"><h3>최근 14일</h3><div class="panel">'+bars+'</div></section>'+
  '<section class="stack"><h3>급수별 진도</h3><div class="panel">'+lvRows+'</div></section>'+
  '<section class="stack"><h3>모의 시험 기록</h3>'+(ex.length?'<div class="list">'+ex.map(x=>'<div class="item"><span class="glyph lvg">N'+x.lv+'</span><span class="grow"><span class="t num">'+x.score+' / '+x.n+'</span><span class="small muted num">'+x.at.slice(0,16)+' · 어휘 '+x.v[0]+'/'+x.v[1]+' · 문법 '+x.g[0]+'/'+x.g[1]+'</span></span></div>').join('')+'</div>':'<p class="muted small">아직 본 모의 시험이 없습니다.</p>')+'</section>'}

/* mock exam */
let EXT=0;
function examQs(lv){const pool=DB.lv[lv],ws_=shuffle(pool).slice(0,20),out=[];
  for(const w of ws_){if(out.length>=10)break;const o=shuffle(pickOther(pool,'ko',w.ko).concat(w.ko));if(o.length===4)out.push({sec:'어휘',ask:'뜻을 고르세요',s:w.jp,o,ans:o.indexOf(w.ko),wid:w.id})}
  for(const w of ws_.slice(10)){if(out.length>=15)break;if(w.kana===w.jp)continue;const o=shuffle(pickOther(pool,'kana',w.kana).concat(w.kana));if(o.length===4)out.push({sec:'어휘',ask:'읽는 법을 고르세요',s:w.jp,o,ans:o.indexOf(w.kana),wid:w.id,jp:true})}
  for(const L of shuffle(LESSONS.filter(l=>l.lv===lv))){if(out.length>=25)break;const qs=lessonQs(L).filter(q=>!q.ord&&!q.kr&&q.s.includes('___'));if(!qs.length)continue;const q=qs[Math.floor(Math.random()*qs.length)],o=shuffle(q.o);out.push({sec:'문법',ask:'빈칸에 알맞은 말을 고르세요',s:q.s,k:q.k,o,ans:o.indexOf(q.o[0]),lid:L.id,jp:true})}
  return out}
const mmss=t=>{t=Math.max(0,Math.round(t/1000));return Math.floor(t/60)+':'+String(t%60).padStart(2,'0')};
function examTick(){const s=V.stack[V.stack.length-1];if(!s||s.type!=='exam'||s.phase!=='run'){clearInterval(EXT);EXT=0;return}
  const left=s.end-Date.now(),el=document.getElementById('extime');if(el)el.textContent=mmss(left);if(left<=0)examFinish(s)}
function examFinish(s){clearInterval(EXT);EXT=0;s.phase='done';let v=[0,0],g=[0,0];s.qs.forEach((q,i)=>{const ok=s.picks[i]===q.ans,t=q.sec==='어휘'?v:g;t[1]++;if(ok)t[0]++;if(q.wid)grade(q.wid,ok)});
  s.res={v,g,score:v[0]+g[0]};S.exams.push({lv:s.lv,at:today()+' '+new Date().toTimeString().slice(0,5),score:s.res.score,n:s.qs.length,v,g});save();render(true)}
function vExam(s){
  if(s.phase==='setup'){const ex=S.exams.filter(x=>x.lv===s.lv).slice(-3).reverse();
    return '<h2>모의 시험</h2><p class="muted">급수를 고르면 어휘 15문제와 문법 10문제가 섞여 나옵니다. 제한 시간은 25분이고, 다 풀거나 시간이 끝나면 채점합니다.</p>'+
    '<div class="seg" role="group" aria-label="시험 급수">'+LV.map(n=>'<button data-a="exlv" data-v="'+n+'" aria-pressed="'+(s.lv===n)+'">N'+n+'</button>').join('')+'</div>'+
    '<button class="btn" data-a="exstart"'+(DB.ready?'':' disabled')+'>N'+s.lv+' 시험 시작</button>'+
    (ex.length?'<section class="stack"><h3>N'+s.lv+' 최근 기록</h3><div class="list">'+ex.map(x=>'<div class="item"><span class="grow"><span class="t num">'+x.score+' / '+x.n+'</span><span class="small muted num">'+x.at.slice(0,16)+' · 어휘 '+x.v[0]+'/'+x.v[1]+' · 문법 '+x.g[0]+'/'+x.g[1]+'</span></span></div>').join('')+'</div></section>':'')}
  if(s.phase==='run'){const q=s.qs[s.i],n=s.qs.length,answered=s.picks.filter(x=>x!=null).length;
    return '<div class="exbar"><span class="pill due">N'+s.lv+' '+q.sec+'</span><span class="small muted num">'+answered+' / '+n+' 답함</span><span class="timer num" aria-label="남은 시간"><span id="extime">'+mmss(s.end-Date.now())+'</span></span></div>'+prog(s.i,n)+
    '<div class="panel"><p class="ask">'+q.ask+'</p><p class="sentence"'+(q.jp?' lang="ja"':'')+'>'+esc(q.s).replace('___','<span class="blank">'+(s.picks[s.i]!=null?esc(q.o[s.picks[s.i]]):'　')+'</span>')+'</p>'+(q.k?'<p class="note">'+esc(q.k)+'</p>':'')+
    '<div class="opts">'+q.o.map((o,i)=>'<button class="opt'+(q.jp?' jp':'')+(s.picks[s.i]===i?' picked':'')+'" data-a="expick" data-v="'+i+'" aria-pressed="'+(s.picks[s.i]===i)+'">'+esc(o)+'</button>').join('')+'</div></div>'+
    '<div class="cardnav"><button class="btn quiet navb" data-a="exprev" aria-label="이전 문제"'+(s.i?'':' disabled')+'>‹</button>'+(s.i+1<n?'<button class="btn" data-a="exnext">다음 문제</button>':'<button class="btn" data-a="exdone">'+(V.exarm?'한 번 더 누르면 제출합니다':'제출하고 채점')+'</button>')+'<button class="btn quiet navb" data-a="exnext" aria-label="다음 문제"'+(s.i+1<n?'':' disabled')+'>›</button></div>'+
    (s.i+1<n?'<button class="btn quiet small" data-a="exdone">'+(V.exarm?'한 번 더 누르면 지금 제출합니다':'지금 제출하고 채점')+'</button>':'')}
  const r=s.res,wrong=s.qs.map((q,i)=>({q,i})).filter(x=>s.picks[x.i]!==x.q.ans);
  return '<div class="panel"><h3>N'+s.lv+' 모의 시험 결과</h3><p class="today big"><span class="hl num">'+r.score+' / '+s.qs.length+'</span> 점</p><div class="stats"><div><b class="num">'+r.v[0]+' / '+r.v[1]+'</b><span class="small muted">어휘</span></div><div><b class="num">'+r.g[0]+' / '+r.g[1]+'</b><span class="small muted">문법</span></div></div><p class="small muted">어휘 문제 결과는 단어 복습 기록에도 반영했습니다.</p></div>'+
  (wrong.length?'<section class="stack"><h3>틀린 문제</h3><div class="list">'+wrong.map(x=>{const q=x.q,p=s.picks[x.i];return '<button class="item" data-a="'+(q.wid?'card1':'lesson')+'" data-v="'+(q.wid||q.lid)+'"><span class="grow"><span class="t jp" lang="ja">'+esc(q.s.replace('___','（'+q.o[q.ans]+'）'))+'</span><span class="small muted">정답 '+esc(q.o[q.ans])+' · 고른 답 '+(p!=null?esc(q.o[p]):'없음')+'</span></span><span class="side small">'+q.sec+'</span></button>'}).join('')+'</div></section>':'')+
  '<div class="row-btns"><button class="btn" data-a="exagain">다시 보기</button><button class="btn quiet" data-a="back">돌아가기</button></div>'}

/* kanji */
const KLV=c=>(DB.kinfo[c]||[0])[0];
function kanjiList(){const f=V.kl||String(S.lv),q=(V.kq||'').trim();const all=Object.keys(DB.kinfo);
  if(q)return all.filter(c=>c===q||q.includes(c)||(DB.kanji[c]&&DB.kanji[c][1].includes(q))||(DB.kinfo[c][4]||'').includes(q)||(DB.kinfo[c][2]+DB.kinfo[c][3]).includes(hira(q))||(DB.kinfo[c][2]).includes(q));
  return all.filter(c=>String(KLV(c))===f)}
function kgrid(list){return list.length?'<p class="small muted num">'+list.length+'자</p><div class="kgrid">'+list.map(c=>'<button class="kb" data-a="kanji" data-v="'+c+'" lang="ja" aria-label="'+c+' '+esc((DB.kanji[c]||['',''])[1])+'">'+c+'</button>').join('')+'</div>':'<p class="muted small">맞는 한자가 없습니다. 한자, 훈음(예: 물을 문), 읽기로 찾을 수 있습니다.</p>'}
function vKanji(){if(!DB.ready)return '<h2>한자</h2>'+loading();const f=V.kl||String(S.lv);
  return '<h2>한자</h2><p class="muted">단어 목록에 나오는 한자 '+fmt(Object.keys(DB.kinfo).length)+'자. 급수는 그 한자가 처음 나오는 단어의 급수입니다. 한자를 누르면 한국 훈음, 음독·훈독, 그 한자가 들어간 단어가 나옵니다.</p>'+
  '<label class="search"><span class="small muted">한자 찾기</span><input id="kq" type="search" autocomplete="off" placeholder="問 · 물을 · もん" value="'+esc(V.kq||'')+'"></label>'+
  '<div class="seg" role="group" aria-label="급수 고르기">'+LV.map(n=>'<button data-a="kl" data-v="'+n+'" aria-pressed="'+(!V.kq&&f===String(n))+'">N'+n+'</button>').join('')+'</div><div id="kres" class="stack">'+kgrid(kanjiList())+'</div>'}
function vKanjiCard(s){const c=s.c,ki=DB.kinfo[c]||[0,0,'','',''],k=DB.kanji[c]||['',''],ids=s.ids&&s.ids.includes(c)?s.ids:(s.ids=[c]),i=ids.indexOf(c);
  const words=[];for(const lv of LV)for(const w of DB.lv[lv]){if(w.jp.includes(c)){words.push(w);if(words.length>=40)break}}
  return prog(i,ids.length)+'<div class="cardnav"><button class="btn quiet navb" data-a="kprev" aria-label="이전 한자"'+(i?'':' disabled')+'>‹</button><span class="navmid small muted">옆으로 밀거나 화살표로 넘기세요</span><button class="btn quiet navb" data-a="knext" aria-label="다음 한자"'+(i+1<ids.length?'':' disabled')+'>›</button></div>'+
  '<div class="panel card"><div class="cardtop"><span class="small muted">'+(ki[0]?'N'+ki[0]+' 단어 한자 · ':'')+(ki[1]?ki[1]+'획':'')+'</span><button class="savebtn" data-a="report" data-v="k:'+c+'">신고</button></div><div class="cells" lang="ja" style="--n:2"><span class="cell">'+c+'</span>'+(k[0]?'<span class="cell old" lang="ko">'+k[0]+'</span>':'')+'</div>'+
  (k[0]?'<p class="note">왼쪽은 일본 글자, 오른쪽은 한국에서 쓰는 정자입니다.</p>':'')+'<p class="meaning">'+esc(k[1])+'</p>'+(ki[4]?'<p class="note">'+esc(ki[4])+'</p>':'')+
  '<div class="kread"><div><span class="small muted">음독</span><span class="jp" lang="ja">'+(esc(ki[2])||'–')+'</span></div><div><span class="small muted">훈독</span><span class="jp" lang="ja">'+(esc(ki[3])||'–')+'</span></div></div></div>'+
  '<section class="stack"><h3>이 한자가 들어간 단어'+(words.length>=40?' · 앞의 40개':'')+'</h3>'+(words.length?'<div class="list">'+words.map(w=>wordRow(w,'N'+w.lv)).join('')+'</div>':'<p class="muted small">단어 목록에 이 한자가 들어간 단어가 없습니다.</p>')+'</section>'}

/* sync (artifact only) */
const SY={on:false,msg:'',col:null,last:{},t:0,busy:false};
function syncParts(){const w=[{},{},{},{},{},{}];for(const k in S.w){const n=parseInt(k.replace(/\D/g,''),10)||0;w[n%6][k]=S.w[k]}
  const rest=Object.assign({},S);delete rest.w;const p={meta:JSON.stringify(rest)};w.forEach((x,i)=>p['w'+i]=JSON.stringify(x));return p}
async function syncPush(){if(!SY.on||SY.busy)return;SY.busy=true;try{const p=syncParts();
    for(const k of Object.keys(p).filter(k=>k!=='meta').concat('meta')){if(SY.last[k]===p[k])continue;await SY.col.doc(k).set({at:S.at,s:p[k]});SY.last[k]=p[k]}
    SY.msg='Claude 계정으로 동기화되었습니다. 마지막 저장 '+new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}catch(e){SY.msg='동기화하지 못했습니다. 잠시 뒤 다시 시도합니다.'}SY.busy=false}
async function syncPull(){const m=await SY.col.doc('meta').get();if(!m.exists)return false;const md=m.data();if(!(md.at>(S.at||0)))return false;
  const o=Object.assign(blank(),JSON.parse(md.s));o.set=Object.assign(blank().set,o.set||{});o.w={};SY.last.meta=md.s;
  for(let i=0;i<6;i++){const d=await SY.col.doc('w'+i).get();if(d.exists){const x=d.data();Object.assign(o.w,JSON.parse(x.s));SY.last['w'+i]=x.s}}
  S=o;try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}applySettings();return true}
async function syncInit(){if(window.STANDALONE||!window.claude||!claude.use)return;try{const [db,user]=await Promise.all([claude.use('db'),claude.use('user')]);
    if(!db||!user){SY.msg='이 화면에서는 자동 동기화를 쓸 수 없습니다. 백업 코드로 옮기세요.';return}
    const uid=await user.id();if(!uid){SY.msg='로그인하면 기기 간 자동 동기화가 켜집니다.';return}
    SY.col=db.collection('data/users/'+uid);SY.on=true;const pulled=await syncPull();if(pulled){FLASH='다른 기기의 학습 기록을 불러왔습니다.';render()}else await syncPush();
    if(!SY.msg)SY.msg='Claude 계정으로 동기화되었습니다.';
    document.addEventListener('visibilitychange',async()=>{if(document.visibilityState==='visible'&&SY.on){try{if(await syncPull())render()}catch(e){}}})}catch(e){SY.msg='동기화를 시작하지 못했습니다. 백업 코드로 옮길 수 있습니다.'}}

/* ---------- views ---------- */
function vHome(){const ids=todayIds(),L=todayLesson(),gdue=dueLessons().length,lt=S.log[today()]||{};
  const gdone=LESSONS.filter(l=>S.g[l.id]&&S.g[l.id].done).length;
  let prog=loading(),weak='';
  if(DB.ready){const st=lvStat(S.lv),tot=DB.lv[S.lv].length;
    prog='<div class="panel"><div class="stats"><div><b class="num">'+fmt(st.m)+'</b><span class="small muted">/ '+fmt(tot)+' N'+S.lv+' 외운 단어</span></div><div><b class="num">'+st.l+'</b><span class="small muted">익히는 중</span></div><div><b class="num">'+gdone+'</b><span class="small muted">/ '+LESSONS.length+' 문법</span></div></div>'+
     '<div class="bar" role="img" aria-label="외운 단어 비율"><i style="width:'+(st.m/tot*100).toFixed(1)+'%"></i></div>'+
     '<p class="small muted">퀴즈나 카드에서 세 번 연달아 맞히면 외운 단어로 셉니다.'+(SY.on?' 기록은 Claude 계정으로 동기화됩니다.':' 기록은 이 브라우저에 저장됩니다.')+'</p></div>';
    const weakW=studied().filter(w=>ws(w.id).m>0).sort((x,y)=>ws(y.id).m-ws(x.id).m).slice(0,5);
    const weakG=LESSONS.filter(l=>S.g[l.id]&&S.g[l.id].miss>0).sort((x,y)=>S.g[y.id].miss-S.g[x.id].miss).slice(0,3);
    if(!weakW.length&&!weakG.length)weak='<p class="muted small">아직 틀린 문제가 없습니다. 퀴즈를 풀면 자주 틀리는 단어와 문형이 여기에 모입니다.</p>';
    else{weak='<div class="list">'+weakW.map(w=>wordRow(w,'<span class="num">'+ws(w.id).m+'번 틀림</span>')).join('')+
      weakG.map(l=>'<button class="item" data-a="lesson" data-v="'+l.id+'"><span class="grow"><span class="t jp" lang="ja">'+l.t+'</span><span class="small muted">문법</span></span><span class="side num">'+S.g[l.id].miss+'번 틀림</span></button>').join('')+'</div>';
      if(weakW.length)weak+='<button class="btn ghost" data-a="weakquiz">틀린 단어만 다시 풀기</button>'}
    const wk=weakKeys();if(wk.length)weak+='<div class="panel"><p><b>활용 약점</b> · '+wk.slice(0,3).map(k=>keyLabel(k)+' '+Math.round(S.cst[k].ok/(S.cst[k].ok+S.cst[k].ng)*100)+'%').join(', ')+'</p><button class="btn ghost" data-a="cdrill" data-v="weak">약한 형태 드릴 10문제</button></div>'}
  return flash()+'<section class="panel today"><h3>오늘의 복습</h3><p class="big">단어 <span class="hl num">'+(DB.ready?ids.length:10)+'개</span>와 문법 <span class="hl jp" lang="ja">'+L.t+'</span></p>'+
   '<p class="muted small num">오늘 새 단어 '+(lt.n||0)+' / '+S.set.nw+'개 · 복습 '+(lt.r||0)+'개 · 복습할 문법 '+gdue+'개. 목표는 설정에서 바꿀 수 있습니다.</p>'+seg()+
   '<div class="row-btns"><button class="btn" data-a="today"'+(ids.length?'':' disabled')+'>단어 복습 시작</button><button class="btn ghost" data-a="lesson" data-v="'+L.id+'">'+(gdue?'문법 복습하기':'오늘의 문법 보기')+'</button></div></section>'+
   '<div class="row-btns three"><button class="btn quiet" data-a="stats">학습 통계</button><button class="btn quiet" data-a="exam">모의 시험</button><button class="btn quiet" data-a="settings">설정</button></div>'+
   '<section class="stack"><h3>진도</h3>'+prog+'</section>'+(DB.ready?'<section class="stack"><h3>약점</h3>'+weak+'</section>':'')+
   ''}
function backupCode(){return JSON.stringify({app:'kotoba-note',v:2,at:new Date().toISOString(),data:S})}
function backupHTML(){const k=V.bk,n=Object.keys(S.w).length;
  if(!k.open)return '<section class="stack"><h3>백업과 복구</h3><button class="btn quiet" data-a="bkopen">저장 데이터 백업 · 복구 열기</button></section>';
  return '<section class="stack"><h3>백업과 복구</h3><div class="panel"><p class="small muted">학습 기록 '+fmt(n)+'단어, 단어장 '+S.book.length+'개, 저장한 문법 '+S.gbook.length+'개, 문법 진도가 백업 코드 하나에 담깁니다. 다른 기기나 브라우저에서 이 코드로 복구할 수 있습니다.</p>'+
   '<div class="row-btns"><button class="btn" data-a="bkmake">백업 코드 만들기</button>'+(window.STANDALONE?'<button class="btn ghost" data-a="bkfile">파일로 저장</button>':'')+'</div>'+
   (k.code?'<label class="search"><span class="small muted">백업 코드 · 전체를 복사해 메모나 메일에 보관하세요</span><textarea id="bkout" class="bk" readonly rows="4">'+esc(k.code)+'</textarea></label><button class="btn ghost" data-a="bkcopy">코드 복사</button>':'')+
   '<label class="search"><span class="small muted">복구 · 백업 코드를 붙여 넣거나 백업 파일을 고르세요</span><textarea id="bkin" class="bk" rows="4" placeholder="{&quot;app&quot;:&quot;kotoba-note&quot;, …}"></textarea></label>'+
   '<input id="bkpick" type="file" accept=".json,.txt,application/json,text/plain" class="small">'+
   '<button class="btn quiet" data-a="bkrestore">'+(k.arm?'지금 기록을 덮어씁니다. 한 번 더 누르면 복구됩니다':'이 코드로 복구하기')+'</button>'+
   (k.msg?'<p class="verdict '+(k.ok?'ok':'no')+'" role="status">'+k.msg+'</p>':'')+'</div></section>'}
function restoreFrom(text){let o;try{o=JSON.parse(text)}catch(e){return '백업 코드를 읽을 수 없습니다. 처음부터 끝까지 빠짐없이 붙여 넣었는지 확인하세요.'}
  const d=o&&o.app==='kotoba-note'?o.data:o;if(!d||typeof d.w!=='object'||typeof d.g!=='object')return '코토바 노트의 백업 코드가 아닙니다.';
  S=Object.assign(blank(),d);S.set=Object.assign(blank().set,d.set||{});S.cst=S.cst&&typeof S.cst==='object'?S.cst:{};['my','book','gbook','folders','reports','exams'].forEach(k=>{if(!Array.isArray(S[k]))S[k]=[]});['log','memo'].forEach(k=>{if(!S[k]||typeof S[k]!=='object')S[k]={}});applySettings();if(!LV.includes(S.lv))S.lv=5;save();return ''}
function searchHTML(){const q=V.q.trim();if(!q||!DB.ready)return'';const res=[];let n=0;
  for(const lv of LV)for(const w of DB.lv[lv]){if(w.jp.includes(q)||w.kana.includes(q)||w.ko.includes(q)){n++;if(res.length<30)res.push(w)}}
  if(!n)return '<p class="muted small">"'+esc(q)+'"에 맞는 단어가 없습니다. 한자, 히라가나, 한국어 뜻으로 찾을 수 있습니다.</p>';
  return '<p class="muted small num">'+fmt(n)+'개 찾음'+(n>30?' · 앞의 30개만 표시':'')+'</p><div class="list">'+res.map(w=>wordRow(w,'N'+w.lv)).join('')+'</div>'}
const vmSeg=()=>'<div class="seg" role="group" aria-label="단어 보기"><button data-a="vm" data-v="lv" aria-pressed="'+(V.vm!=='book')+'">급수별 단어</button><button data-a="vm" data-v="book" aria-pressed="'+(V.vm==='book')+'">내 단어장 '+S.book.length+'</button></div>';
function vVocab(){if(!DB.ready)return '<h2>단어</h2>'+loading();if(V.vm==='book')return '<h2>단어</h2>'+vmSeg()+vBook();
  return '<h2>단어</h2>'+vmSeg()+'<p class="muted">JLPT N5부터 N1까지 '+fmt(DB.total)+'개. 카드마다 히라가나, 뜻, 한국 한자, 예문이 들어 있습니다.</p>'+
  '<label class="search"><span class="small muted">단어 찾기</span><input id="q" type="search" autocomplete="off" placeholder="約束 · やくそく · 약속" value="'+esc(V.q)+'"></label><div id="qres" class="stack">'+searchHTML()+'</div>'+
  '<div class="list">'+LV.map(n=>{const st=lvStat(n),tot=DB.lv[n].length;
    return '<button class="item" data-a="level" data-v="'+n+'"><span class="glyph lvg">N'+n+'</span><span class="grow"><span class="t">JLPT N'+n+'</span><span class="small muted num">'+fmt(tot)+'개 · '+Math.ceil(tot/SET)+'세트</span></span><span class="side num">'+fmt(st.m)+' / '+fmt(tot)+(st.due?'<br><span class="pill due">복습 '+st.due+'</span>':'')+'</span></button>'}).join('')+
  '</div>'+
  '<p class="src small muted">단어의 표기, 읽기, 한국어 뜻, 예문은 <a href="https://github.com/Alfex4936/JLPT" target="_blank" rel="noopener">Alfex4936/JLPT</a> 자료입니다. 목록은 tanos.co.uk의 JLPT 어휘 목록에서 왔고, 뜻과 예문은 AI가 만든 것으로 사람이 전부 검수하지는 않았습니다. 한국 한자 표기와 음은 <a href="https://github.com/BYVoid/OpenCC" target="_blank" rel="noopener">OpenCC</a>(Apache-2.0)와 <a href="https://github.com/libhangul/libhangul" target="_blank" rel="noopener">libhangul</a> 한자 사전으로 계산했으며, 훈음 일부는 KANJIDIC2(EDRDG, CC BY-SA 4.0)에서 파생되었습니다. JLPT는 공식 단어 목록을 공개하지 않으므로 급수 구분은 비공식입니다.</p>'}
function vLevel(s){const list=DB.lv[s.lv],n=Math.ceil(list.length/SET);let first=-1,h='';
  for(let i=0;i<n;i++){const ws_=list.slice(i*SET,(i+1)*SET),m=ws_.filter(w=>ws(w.id).b>=3).length,t=ws_.filter(w=>ws(w.id).b>0).length;
    if(first<0&&t<ws_.length)first=i;
    h+='<button class="setb'+(m===ws_.length?' done':t?' part':'')+'" data-a="set" data-v="'+i+'" aria-label="'+(i+1)+'세트, '+m+'개 외움"><span class="num">'+(i+1)+'</span><span class="bar"><i style="width:'+Math.round(m/ws_.length*100)+'%"></i></span></button>'}
  return '<h2>JLPT N'+s.lv+'</h2><p class="muted num">'+fmt(list.length)+'개를 '+SET+'개씩 '+n+'세트로 나눴습니다. 막대는 외운 비율입니다.</p>'+
  (first>=0?'<button class="btn" data-a="set" data-v="'+first+'">'+(first+1)+'세트부터 이어서 보기</button>':'')+'<div class="sets">'+h+'</div>'}
function vDeck(s){const w=deckWords(s),a=s.set*SET;
  return '<h2>N'+s.lv+' · '+(s.set+1)+'세트</h2><p class="muted num">'+(a+1)+'번부터 '+(a+w.length)+'번까지 · 단어를 누르면 카드가 열립니다.</p><div class="row-btns"><button class="btn" data-a="cards">카드로 보기</button><button class="btn ghost" data-a="quizdeck">퀴즈 풀기</button></div>'+qmSeg()+
  '<div class="list">'+w.map(x=>wordRow(x,boxes(ws(x.id).b))).join('')+'</div>'+
  ((s.set+1)*SET<DB.lv[s.lv].length?'<button class="btn quiet" data-a="nextset">다음 세트</button>':'')}
function prog(i,n){return '<div class="prog"><div class="bar"><i style="width:'+Math.round(i/n*100)+'%"></i></div><span class="small muted num">'+(i+1)+' / '+n+'</span></div>'}
function vBook(){if(!DB.ready)return loading();const w=bookWords(),cur=S.folders.find(f=>f.id===V.bf);
  const fs='<div class="chips folders"><button class="chip'+(!V.bf?' in':'')+'" data-a="bf" data-v="" aria-pressed="'+!V.bf+'">기본 '+S.book.length+'</button>'+S.folders.map(f=>'<button class="chip'+(V.bf===f.id?' in':'')+'" data-a="bf" data-v="'+f.id+'" aria-pressed="'+(V.bf===f.id)+'">'+esc(f.name)+' '+f.ids.length+'</button>').join('')+'</div>'+
    '<div class="inline"><input id="fnew2" maxlength="20" placeholder="새 폴더 이름"><button class="btn quiet" data-a="fadd2">폴더 만들기</button></div>';
  const head=fs;
  if(!w.length)return head+'<div class="panel"><p>'+(cur?'"'+esc(cur.name)+'" 폴더가 비어 있습니다.':'아직 저장한 단어가 없습니다.')+'</p><p class="muted">'+(cur?'카드 위쪽의 "폴더"를 눌러 이 폴더에 담으세요.':'카드 위쪽의 "단어장에 저장"을 누르면 여기에 모입니다. 문법 레슨의 예문 단어도 여기에 담깁니다.')+'</p>'+(cur?'<button class="btn quiet" data-a="fdel">'+(V.fdel?'한 번 더 누르면 폴더를 지웁니다':'이 폴더 지우기')+'</button>':'<button class="btn" data-a="vm" data-v="lv">단어 보러 가기</button>')+'</div>';
  return head+'<p class="muted num">'+(cur?esc(cur.name)+' · ':'')+fmt(w.length)+'개 · 최근에 담은 순서입니다.</p><div class="row-btns"><button class="btn" data-a="bookcards">카드로 보기</button><button class="btn ghost" data-a="bookquiz">퀴즈 풀기</button></div>'+qmSeg()+
  '<div class="list">'+w.map(x=>'<button class="item" data-a="card1" data-v="'+esc(x.id)+'"><span class="grow"><span class="wline"><span class="w" lang="ja">'+esc(x.jp)+'</span><span class="small muted" lang="ja">'+esc(x.kana)+'</span></span><span>'+esc(x.ko)+'</span>'+(S.memo[x.id]?'<span class="small memoline">메모 · '+esc(S.memo[x.id].slice(0,60))+'</span>':'')+'</span><span class="side">'+(x.lv?'N'+x.lv:'문법')+'</span></button>').join('')+'</div>'+
  (cur?'<button class="btn quiet small" data-a="fdel">'+(V.fdel?'한 번 더 누르면 폴더를 지웁니다 (단어는 남습니다)':'이 폴더 지우기')+'</button>':'')}
function vCards(s){const w=byId(s.ids[s.i]),n=s.ids.length,show=s.browse||s.flip||S.open;
  const prev='<button class="btn quiet navb" data-a="cprev" aria-label="이전 카드"'+(s.i?'':' disabled')+'>‹</button>',next='<button class="btn quiet navb" data-a="cnext" aria-label="다음 카드"'+(s.i+1<n?'':' disabled')+'>›</button>';
  let mid;if(s.browse)mid='<span class="navmid small muted">옆으로 밀거나 화살표로 넘기세요</span>';
  else if(show)mid='<button class="btn quiet" data-a="cardgrade" data-v="0">몰라요</button><button class="btn" data-a="cardgrade" data-v="1">알아요</button>';
  else mid='<button class="btn" data-a="flip">뒤집기</button>';
  return prog(s.i,n)+'<div class="cardnav">'+prev+mid+next+'</div>'+
  '<div class="panel card">'+cardTop(w)+cells(w.jp)+(show?detail(w):'<p class="ask">읽는 법과 뜻을 떠올린 다음 뒤집어 보세요.</p>')+'</div>'+
  (s.browse?'':'<button class="btn quiet small" data-a="toggleopen" aria-pressed="'+S.open+'">'+(S.open?'뜻을 가리고 시작하기':'처음부터 전부 펼쳐 보기')+'</button>')}
function vQuiz(s){const w=byId(s.ids[s.i]),q=s.q,done=s.sel!==null;let h=prog(s.i,s.ids.length)+'<div class="panel">';
  const opts=(jp)=>'<div class="opts">'+q.opts.map((o,i)=>'<button class="opt'+(jp?' jp':'')+(done&&i===q.ans?' right':done&&i===s.sel?' wrong':'')+'" data-a="ans" data-v="'+i+'"'+(done?' disabled':'')+'>'+esc(o)+'</button>').join('')+'</div>';
  if(q.type==='type')h+=cells(w.jp)+'<p class="ask">'+esc(w.ko)+'<br>읽는 법을 히라가나로 쓰세요</p><form class="inline" data-f="type"><input id="tin" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="ひらがな"'+(done?' disabled value="'+esc(s.typed)+'"':'')+'><button class="btn"'+(done?' disabled':'')+'>확인</button></form>';
  else if(q.type==='listen')h+='<p class="ask">소리를 듣고 뜻을 고르세요</p><button class="btn ghost" data-a="relisten">다시 듣기</button>'+(done?cells(w.jp):'')+opts(false);
  else if(q.type==='order'){const full=!q.pool.length;h+='<p class="ask">한국어 문장에 맞게 조각을 차례로 누르세요</p><p class="meaning">'+esc(w.exko)+'</p>'+
    '<div class="tray" lang="ja">'+q.built.map((x,i)=>'<button class="tile" data-a="qun" data-v="'+i+'"'+(done?' disabled':'')+'>'+esc(q.c[x])+'</button>').join('')+'</div>'+
    '<div class="tiles" lang="ja">'+q.pool.map((x,i)=>'<button class="tile" data-a="qtile" data-v="'+i+'">'+esc(q.c[x])+'</button>').join('')+'</div>'+(done?'':'<button class="btn" data-a="qcheck"'+(full?'':' disabled')+'>확인</button>')}
  else h+=cells(w.jp)+'<p class="ask">'+(q.type==='ko'?'뜻을 고르세요':'읽는 법을 고르세요')+'</p>'+opts(q.type==='kana');
  h+='</div>';
  if(done)h+='<div class="panel card"><p class="verdict '+(s.okq?'ok">맞았습니다':'no">틀렸습니다. 10분 뒤 복습에 다시 나옵니다')+'</p>'+(q.type==='order'?'<p class="sentence" lang="ja">'+esc(q.c.join(''))+'</p>':'')+cardTop(w)+(q.type==='order'?cells(w.jp):'')+detail(w)+'</div><button class="btn" data-a="next">'+(s.i+1<s.ids.length?'다음 문제':'결과 보기')+'</button>';
  return h}
function vResult(s){const wrong=s.wrong.map(byId).filter(Boolean);
  return '<div class="panel"><h3>'+s.label+'</h3><p class="today big"><span class="hl num">'+s.n+'문제 중 '+s.right+'개</span> 맞혔습니다</p>'+
  (s.msg?'<p class="muted">'+s.msg+'</p>':'')+'</div>'+
  (wrong.length?'<section class="stack"><h3>틀린 단어</h3><div class="list">'+wrong.map(w=>wordRow(w,'')).join('')+'</div></section>':'')+
  '<div class="row-btns">'+(wrong.length?'<button class="btn" data-a="retry">틀린 것만 다시</button>':'')+(s.drill?'<button class="btn ghost" data-a="cdrill" data-v="'+s.drill+'">다시 풀기</button>':'')+(s.lesson?'<button class="btn ghost" data-a="practice" data-v="'+s.lesson+'">다시 풀기</button>':'')+'<button class="btn quiet" data-a="back">돌아가기</button></div>'}
const gSaved=id=>S.gbook.includes(id);
function vGrammar(){const f=V.gf||String(S.lv),saved=LESSONS.filter(l=>gSaved(l.id)),list=f==='saved'?saved:LESSONS.filter(l=>String(l.lv)===f);
  const done=list.filter(l=>!undone(l)).length;
  return '<h2>문법</h2><p class="muted">JLPT 급수별 문형 '+LESSONS.length+'개. 접속 형태, 쓰임, 한국어와 다른 점, 예문, 연습 문제가 들어 있습니다.</p>'+(dueLessons().length?'<button class="btn ghost" data-a="lesson" data-v="'+dueLessons()[0].id+'">복습할 문법 '+dueLessons().length+'개 · 첫 문형부터 보기</button>':'')+
  '<div class="seg" role="group" aria-label="급수 고르기">'+LV.map(n=>'<button data-a="gf" data-v="'+n+'" aria-pressed="'+(f===String(n))+'">N'+n+'</button>').join('')+'<button data-a="gf" data-v="conj" aria-pressed="'+(f==='conj')+'">활용</button><button data-a="gf" data-v="saved" aria-pressed="'+(f==='saved')+'">저장 '+saved.length+'</button></div>'+
  (f==='conj'?vConjHome():list.length?'<p class="small muted num">'+list.length+'개 중 '+done+'개 완료</p><div class="list">'+list.map(l=>{const g=S.g[l.id];return '<button class="item" data-a="lesson" data-v="'+l.id+'"><span class="grow"><span class="t jp" lang="ja">'+l.t+'</span><span class="small muted">'+l.ko+'</span></span><span class="side">'+(f==='saved'?'N'+l.lv+' ':'')+(f!=='saved'&&gSaved(l.id)?'<span class="pill due">저장</span> ':'')+(g&&g.d&&g.d<=Date.now()?'<span class="pill due">복습</span> ':'')+(g&&g.done?'<span class="pill good">완료 '+g.best+'/'+(g.n||l.qs.length)+'</span>':'')+'</span></button>'}).join('')+'</div>'
   :'<div class="panel"><p>아직 저장한 문법이 없습니다.</p><p class="muted">레슨 위쪽의 "문법 저장"을 누르면 여기에 모입니다. 다시 보고 싶은 문형을 담아 두세요.</p></div>')}
function vLesson(s){const l=LESSONS.find(x=>x.id===s.id);
  const ids=s.ids&&s.ids.includes(l.id)?s.ids:(s.ids=LESSONS.filter(x=>x.lv===l.lv).map(x=>x.id)),li=ids.indexOf(l.id);
  return prog(li,ids.length)+'<div class="cardnav"><button class="btn quiet navb" data-a="lprev" aria-label="이전 문법"'+(li?'':' disabled')+'>‹</button><span class="navmid small muted">옆으로 밀거나 화살표로 넘기세요</span><button class="btn quiet navb" data-a="lnext" aria-label="다음 문법"'+(li+1<ids.length?'':' disabled')+'>›</button></div>'+
  '<div class="cardtop"><h2 class="jp" lang="ja">'+l.t+'</h2><button class="savebtn" data-a="gbook" data-v="'+l.id+'" aria-pressed="'+gSaved(l.id)+'">'+(gSaved(l.id)?'문법 저장됨':'문법 저장')+'</button></div><div class="cardtop"><span class="small muted">'+(S.g[l.id]&&S.g[l.id].d?'다음 복습 '+new Date(S.g[l.id].d).toLocaleDateString('ko-KR',{month:'long',day:'numeric'}):'연습 문제를 풀면 복습 일정이 잡힙니다')+'</span><button class="savebtn quietb" data-a="report" data-v="g:'+l.id+'">신고</button></div><div class="panel"><h3>JLPT N'+l.lv+' 문형</h3>'+(l.pat?'<p class="pattern" lang="ja">'+l.pat+'</p>':'')+'<p class="match"><span class="hl">'+l.ko+'</span></p>'+(l.con?'<div class="con"><span class="small muted">접속</span><span class="jp" lang="ja">'+l.con+'</span></div>':'')+'<ul class="pts">'+l.pts.map(p=>'<li>'+p+'</li>').join('')+'</ul></div>'+
  (l.warn?'<div class="warn"><b>주의할 점</b><span>'+l.warn+'</span></div>':'')+
  '<section class="stack"><h3>예문</h3><div class="panel">'+l.ex.map(e=>'<div class="ex"><span class="jp" lang="ja">'+rich(e[0])+'</span><span class="small muted">'+e[1]+'</span></div>').join('')+(canSpeak?'<button class="speak" data-a="speak" data-v="'+l.ex.map(e=>plain(e[0])).join(' ')+'">예문 듣기</button>':'')+'</div></section>'+
  (!l.voc?'':'<section class="stack"><h3>예문 속 단어 · 누르면 단어장에 담깁니다</h3><div class="chips">'+l.voc.map((v,i)=>{const has=inBook('m:'+v[0]);return '<button class="chip'+(has?' in':'')+'" data-a="addw" data-v="'+l.id+'|'+i+'"'+(has?' disabled':'')+'><span class="jp" lang="ja">'+v[0]+'</span>'+v[2]+(has?' · 담김':'')+'</button>'}).join('')+'</div></section>')+
  (CONJLES[l.id]||CONJLES[l.t]?'<button class="btn ghost" data-a="clesson" data-v="'+(CONJLES[l.id]||CONJLES[l.t])+'">'+(CLK.find(x=>x[0]===(CONJLES[l.id]||CONJLES[l.t]))||[0,''])[1]+' 만드는 법 보기</button>':'')+
  '<button class="btn" data-a="practice" data-v="'+l.id+'">연습 문제 풀기</button>'}
function vPractice(p){const q=p.qs[p.i],n=p.qs.length,last=p.i+1>=n;let h=prog(p.i,n);
  if(q.ord){const full=p.built.length===q.ord.length;
    h+='<div class="panel"><p class="ask">조각을 눌러 문장을 만드세요</p><p class="meaning">'+q.k+'</p>'+
     '<div class="tray" lang="ja">'+p.built.map((x,i)=>'<button class="tile" data-a="untile" data-v="'+i+'"'+(p.checked?' disabled':'')+'>'+q.ord[x]+'</button>').join('')+'</div>'+
     '<div class="tiles" lang="ja">'+p.pool.map((x,i)=>'<button class="tile" data-a="tile" data-v="'+i+'">'+q.ord[x]+'</button>').join('')+'</div></div>';
    if(p.checked)h+='<div class="panel"><p class="verdict '+(p.ok?'ok">맞았습니다':'no">틀렸습니다')+'</p><p class="sentence" lang="ja">'+q.ord.join('')+'。</p><p class="small muted">어순은 한국어와 같습니다. 한국어 문장 순서대로 놓으면 됩니다.</p></div>';
    else h+='<button class="btn" data-a="checkord"'+(full?'':' disabled')+'>확인</button>';
  }else{const done=p.sel!==null,ans=p.opts.indexOf(q.o[0]);
    h+='<div class="panel"><p class="ask">'+(q.ask||'빈칸에 알맞은 말을 고르세요')+'</p><p class="sentence" lang="ja">'+q.s.replace('___','<span class="blank">'+(done?q.o[0]:'　')+'</span>')+'</p>'+(q.k?'<p class="note">'+q.k+'</p>':'')+
     '<div class="opts'+(q.kr?' one':'')+'">'+p.opts.map((o,i)=>'<button class="opt'+(q.kr?'':' jp')+(done&&i===ans?' right':done&&i===p.sel?' wrong':'')+'" data-a="pans" data-v="'+i+'"'+(done?' disabled':'')+'>'+o+'</button>').join('')+'</div></div>';
    if(done)h+='<div class="panel"><p class="verdict '+(p.sel===ans?'ok">맞았습니다':'no">틀렸습니다')+'</p><p class="jp">'+q.why+'</p></div>'}
  if(p.sel!==null||p.checked)h+='<button class="btn" data-a="pnext">'+(last?'결과 보기':'다음 문제')+'</button>';
  return h}

function render(top){const s=V.stack[V.stack.length-1];let body;
  if(s&&!DB.ready&&!['lesson','practice','result','settings','stats','report','display','clesson'].includes(s.type)){V.stack=[];return render(true)}
  if(!s)body=V.tab==='home'?vHome():V.tab==='vocab'?vVocab():V.tab==='kanji'?vKanji():vGrammar();
  else body={level:vLevel,deck:vDeck,cards:vCards,quiz:vQuiz,result:vResult,lesson:vLesson,practice:vPractice,report:vReport,settings:vSettings,display:vDisplay,clesson:vCLesson,cdrill:vCDrill,stats:vStats,exam:vExam,kanji:vKanjiCard}[s.type](s);
  app.innerHTML='<header class="top">'+(s?'<button class="back" data-a="back">‹ 뒤로</button>':'<span class="brand" lang="ja">ことばノート<small lang="ko">JLPT N5–N1 · 한국어 화자용</small></span>')+(s&&(s.type==='display'||s.type==='settings')?'':'<button class="aa" data-a="display" aria-label="화면 설정: 글자 크기와 배경 테마">Aa</button>')+'</header>'+flash()+body;
  ['home','vocab','kanji','grammar'].forEach(t=>{const b=document.getElementById('tab-'+t);if(V.tab===t)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
  if(top)window.scrollTo(0,0)}

document.addEventListener('change',e=>{if(e.target.id!=='bkpick'||!e.target.files[0])return;const r=new FileReader();r.onload=()=>{const t=document.getElementById('bkin');if(t)t.value=String(r.result)};r.readAsText(e.target.files[0])});
let MT=0;document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.dataset.f!=='type')return;const s=V.stack[V.stack.length-1];if(!s||s.type!=='quiz'||s.sel!==null)return;
  const w=byId(s.ids[s.i]),val=document.getElementById('tin').value,n=normKana(val),k=normKana(w.kana);if(!n)return;
  s.typed=val;s.sel=0;s.okq=n===k||n===k.replace(/する$/,'')||n+'する'===k;grade(w.id,s.okq);if(s.okq)s.right++;else s.wrong.push(w.id);render()});
document.addEventListener('change',e=>{if(e.target.id==='voice'){S.set.voice=e.target.value;save();speak('こんにちは')}});
document.addEventListener('input',e=>{if(e.target.id==='memo'){const id=e.target.dataset.id,v=e.target.value.trim();if(v)S.memo[id]=e.target.value;else delete S.memo[id];clearTimeout(MT);MT=setTimeout(save,600);return}
  if(e.target.id==='kq'){V.kq=e.target.value;const r=document.getElementById('kres');if(r)r.innerHTML=kgrid(kanjiList());document.querySelectorAll('[data-a=kl]').forEach(b=>b.setAttribute('aria-pressed',String(!V.kq&&b.dataset.v===(V.kl||String(S.lv)))));return}
  if(e.target.id==='q'){
V.q=e.target.value;const r=document.getElementById('qres');if(r)r.innerHTML=searchHTML()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(!b||b.disabled)return;const a=b.dataset.a,v=b.dataset.v,s=V.stack[V.stack.length-1];
  if(a!=='reset')armed=false;if(a!=='fdel')V.fdel=false;if(a!=='rclear')V.rarm=false;if(a!=='exdone')V.exarm=false;if(a!=='fopen'&&a!=='ftog'&&a!=='fadd')V.fp=null;
  switch(a){
  case 'tab':if(v==='book'){V.tab='vocab';V.vm='book'}else V.tab=v;V.stack=[];render(true);break;
  case 'vm':V.tab='vocab';V.vm=v;V.stack=[];render(true);break;
  case 'back':V.stack.pop();render(true);break;
  case 'reload':loadData();render();break;
  case 'setlv':S.lv=+v;save();render();break;
  case 'today':startQuiz(todayIds());break;
  case 'weakquiz':startQuiz(studied().filter(w=>ws(w.id).m>0).sort((x,y)=>ws(y.id).m-ws(x.id).m).slice(0,10).map(w=>w.id));break;
  case 'level':open({type:'level',lv:+v});break;
  case 'set':open({type:'deck',lv:s.lv,set:+v});break;
  case 'nextset':V.stack.pop();open({type:'deck',lv:s.lv,set:s.set+1});break;
  case 'bookcards':open({type:'cards',ids:bookWords().map(w=>w.id),i:0,flip:false,right:0,wrong:[]});break;
  case 'bookquiz':startQuiz(bookWords().slice(0,20).map(w=>w.id),S.set.qm);break;
  case 'book':{const i=S.book.indexOf(v);if(i>=0)S.book.splice(i,1);else S.book.push(v);save();render();break}
  case 'gf':V.gf=v;render();break;
  case 'bkopen':V.bk.open=true;render();break;
  case 'bkmake':V.bk.code=backupCode();V.bk.msg='백업 코드를 만들었습니다.';V.bk.ok=true;V.bk.arm=false;render();break;
  case 'bkcopy':{const t=document.getElementById('bkout'),done=m=>{V.bk.msg=m;V.bk.ok=true;const p=document.querySelector('[role=status]');if(p)p.textContent=m};
    const fb=()=>{t.focus();t.select();done('코드를 선택했습니다. 복사 메뉴로 복사하세요.')};
    if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t.value).then(()=>done('백업 코드를 복사했습니다.')).catch(fb);else fb();break}
  case 'bkfile':{try{const u=URL.createObjectURL(new Blob([backupCode()],{type:'application/json'})),l=document.createElement('a');l.href=u;l.download='kotoba-note-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(l);l.click();l.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);V.bk.msg='백업 파일을 저장했습니다.';V.bk.ok=true}catch(e){V.bk.msg='파일로 저장하지 못했습니다. 백업 코드를 복사해 보관하세요.';V.bk.ok=false}render();break}
  case 'bkrestore':{const t=document.getElementById('bkin').value.trim();
    if(!t){V.bk.msg='복구할 백업 코드를 먼저 붙여 넣으세요.';V.bk.ok=false;V.bk.arm=false;render();break}
    if(!V.bk.arm){V.bk.arm=true;V.bk.pending=t;V.bk.msg='';render();document.getElementById('bkin').value=t;break}
    const err=restoreFrom(t);V.bk.arm=false;V.bk.code='';V.bk.msg=err||'복구했습니다. 학습 기록과 단어장, 저장한 문법을 불러왔습니다.';V.bk.ok=!err;render();break}
  case 'gbook':{const i=S.gbook.indexOf(v);if(i>=0)S.gbook.splice(i,1);else S.gbook.push(v);save();render();break}
  case 'qm':S.set.qm=v;save();render();break;
  case 'relisten':speak(byId(s.ids[s.i]).kana);break;
  case 'qtile':s.q.built.push(s.q.pool.splice(+v,1)[0]);render();break;
  case 'qun':s.q.pool.push(s.q.built.splice(+v,1)[0]);render();break;
  case 'qcheck':{const id=s.ids[s.i],ok=s.q.built.map(i=>s.q.c[i]).join('')===s.q.c.join('');s.sel=0;s.okq=ok;grade(id,ok);if(ok)s.right++;else s.wrong.push(id);render();break}
  case 'stats':open({type:'stats'});break;
  case 'settings':V.bk.open=true;open({type:'settings'});break;
  case 'exam':open({type:'exam',phase:'setup',lv:S.lv});break;
  case 'exlv':s.lv=+v;render();break;
  case 'exstart':case 'exagain':{const lv=s.lv;V.stack.pop();const qs=examQs(lv);open({type:'exam',phase:'run',lv,qs,i:0,picks:qs.map(()=>null),end:Date.now()+25*60*1000});clearInterval(EXT);EXT=setInterval(examTick,1000);break}
  case 'expick':s.picks[s.i]=+v;render();break;
  case 'exprev':if(s.i>0){s.i--;render(true)}break;
  case 'exnext':if(s.i+1<s.qs.length){s.i++;render(true)}break;
  case 'exdone':if(!V.exarm){V.exarm=true;render();break}V.exarm=false;examFinish(s);break;
  case 'goalnw':S.set.nw=+v;save();render();break;
  case 'goalrv':S.set.rv=+v;save();render();break;
  case 'fz':S.set.fz=+v;save();applySettings();render();break;
  case 'js':S.set.js=+v;save();applySettings();render();break;
  case 'rt':S.set.rt=+v;save();applySettings();render();break;
  case 'lh':S.set.lh=+v;save();applySettings();render();break;
  case 'skin':S.set.skin=v;save();applySettings();render();break;
  case 'dispreset':Object.assign(S.set,{fz:2,js:1,rt:1,lh:1,skin:'auto',furi:true});save();applySettings();render();break;
  case 'display':open({type:'display'});break;
  case 'furi':S.set.furi=v==='1';save();applySettings();render();break;
  case 'rate':S.set.rate=+v;save();render();speak('日本語の発音です');break;
  case 'report':open({type:'report',key:v,kind:''});break;
  case 'rkind':{const t=document.getElementById('rtext').value;s.kind=v;render();document.getElementById('rtext').value=t;break}
  case 'rsend':S.reports.push({key:s.key,kind:s.kind,text:document.getElementById('rtext').value.trim(),at:new Date().toISOString()});save();V.stack.pop();FLASH='신고를 저장했습니다. 설정의 오류 신고 목록에서 모아 보낼 수 있습니다.';render(true);break;
  case 'rcopy':{const t=document.getElementById('rout');const done=()=>{FLASH='신고 목록을 복사했습니다.';render()};if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t.value).then(done).catch(()=>{t.focus();t.select()});else{t.focus();t.select()}break}
  case 'rclear':if(!V.rarm){V.rarm=true;render();break}S.reports=[];V.rarm=false;save();render();break;
  case 'fopen':V.fp=V.fp===v?null:v;render();break;
  case 'ftog':{const i0=v.indexOf('|'),fid=v.slice(0,i0),id=v.slice(i0+1),f=S.folders.find(x=>x.id===fid);if(f){const i=f.ids.indexOf(id);if(i>=0)f.ids.splice(i,1);else f.ids.push(id);save()}V.fp=id;render();break}
  case 'fadd':{const n=document.getElementById('fnew').value.trim();if(!n)break;S.folders.push({id:'f'+Date.now().toString(36),name:n,ids:[v]});save();V.fp=v;render();break}
  case 'fadd2':{const n=document.getElementById('fnew2').value.trim();if(!n)break;const f={id:'f'+Date.now().toString(36),name:n,ids:[]};S.folders.push(f);V.bf=f.id;save();render();break}
  case 'bf':V.bf=v;render();break;
  case 'fdel':if(!V.fdel){V.fdel=true;render();break}S.folders=S.folders.filter(f=>f.id!==V.bf);V.bf='';V.fdel=false;save();render();break;
  case 'kl':V.kl=v;V.kq='';render();break;
  case 'kanji':{if(!DB.kinfo[v]&&!DB.kanji[v])break;const box=b.closest('.kgrid');const ids=box?[...box.querySelectorAll('[data-a=kanji]')].map(x=>x.dataset.v):[v];open({type:'kanji',c:v,ids});break}
  case 'kprev':cardMove(-1);break;
  case 'knext':cardMove(1);break;
  case 'cform':{const i=v.lastIndexOf('|'),id=v.slice(0,i),k=v.slice(i+1);if(!k)break;if(V.cfw===id&&V.cf===k&&!b.closest('.cardnav'))V.cf=null;else{V.cfw=id;V.cf=k}render();if(V.cf){const d=document.querySelector('.cdet');if(d)d.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}break}
  case 'clesson':open({type:'clesson',key:v});break;
  case 'clprev':cardMove(-1);break;
  case 'clnext':cardMove(1);break;
  case 'cdrill':startDrill(v);break;
  case 'dpick':{if(s.sel!==null)break;s.sel=+v;const q=s.qs[s.i],ok=s.sel===q.ans,k=q.key,x=S.cst[k]||(S.cst[k]={ok:0,ng:0});if(ok){x.ok++;s.right++}else x.ng++;logAdd(ok?'ok':'ng');save();render();break}
  case 'dnext':s.i++;if(s.i>=s.qs.length){V.stack.pop();open({type:'result',label:s.title,n:s.qs.length,right:s.right,wrong:[],drill:s.v})}else{s.sel=null;render(true)}break;
  case 'cprev':cardMove(-1);break;
  case 'cnext':cardMove(1);break;
  case 'quizdeck':startQuiz(deckWords(s).map(w=>w.id),S.set.qm);break;
  case 'cards':open({type:'cards',ids:deckWords(s).map(w=>w.id),i:0,flip:false,right:0,wrong:[]});break;
  case 'card1':{if(!byId(v))break;const box=b.closest('.list');const ids=box?[...box.querySelectorAll('[data-a=card1]')].map(x=>x.dataset.v):[v];open({type:'cards',ids,i:Math.max(0,ids.indexOf(v)),browse:true});break}
  case 'flip':s.flip=true;render();break;
  case 'toggleopen':S.open=!S.open;save();render();break;
  case 'cardgrade':{const id=s.ids[s.i],ok=v==='1';grade(id,ok);if(ok)s.right++;else s.wrong.push(id);s.i++;s.flip=false;
    if(s.i>=s.ids.length){V.stack.pop();open({type:'result',label:'카드 훑어보기',n:s.ids.length,right:s.right,wrong:s.wrong})}else render(true);break}
  case 'speak':speak(v);break;
  case 'ans':{s.sel=+v;const id=s.ids[s.i],ok=s.sel===s.q.ans;s.okq=ok;grade(id,ok);if(ok)s.right++;else s.wrong.push(id);render();break}
  case 'next':s.i++;if(s.i>=s.ids.length){V.stack.pop();open({type:'result',label:'단어 퀴즈',n:s.ids.length,right:s.right,wrong:s.wrong})}else{s.sel=null;s.q=makeQ(s.ids[s.i],s.mode);render(true);if(s.q.type==='listen')speak(byId(s.ids[s.i]).kana)}break;
  case 'retry':{const ids=s.wrong;V.stack.pop();startQuiz(ids,S.set.qm);break}
  case 'lesson':{const L=LESSONS.find(l=>l.id===v);if(!L)break;const box=b.closest('.list'),ids=box?[...box.querySelectorAll('[data-a=lesson]')].map(x=>x.dataset.v):null;
    if(b.classList.contains('tk')||b.dataset.keep){open({type:'lesson',id:v,ids});break}
    V.tab='grammar';if(V.gf!=='saved')V.gf=String(L.lv);V.stack=[];open({type:'lesson',id:v,ids});break}
  case 'lprev':cardMove(-1);break;
  case 'lnext':cardMove(1);break;
  case 'addw':{const p=v.split('|'),x=LESSONS.find(l=>l.id===p[0]).voc[+p[1]];
    if(!S.my.some(w=>w.jp===x[0]))S.my.push({id:'m:'+x[0],lv:0,jp:x[0],kana:x[1],ko:x[2],p:'',ex:'',exk:'',exko:'',hw:''});if(!inBook('m:'+x[0]))S.book.push('m:'+x[0]);save();render();break}
  case 'practice':if(s&&s.type==='result')V.stack.pop();startPractice(v);break;
  case 'pans':{s.sel=+v;const ok=s.opts[s.sel]===s.qs[s.i].o[0];if(ok)s.right++;else gmiss(s.L.id);render();break}
  case 'tile':s.built.push(s.pool.splice(+v,1)[0]);render();break;
  case 'untile':s.pool.push(s.built.splice(+v,1)[0]);render();break;
  case 'checkord':s.checked=true;s.ok=s.built.every((x,i)=>x===i);if(s.ok)s.right++;else gmiss(s.L.id);render();break;
  case 'pnext':s.i++;if(s.i>=s.qs.length){const g=S.g[s.L.id]||(S.g[s.L.id]={done:false,miss:0});g.done=true;g.best=Math.max(g.best||0,s.right);g.n=s.qs.length;g.b=s.right/s.qs.length>=.75?Math.min(5,(g.b||0)+1):1;g.d=Date.now()+INTG[g.b];logAdd('g');save();V.stack.pop();
      open({type:'result',label:'문법 연습 · '+s.L.t,n:s.qs.length,right:s.right,wrong:[],lesson:s.L.id,msg:(s.right===s.qs.length?'전부 맞혔습니다. ':'틀린 문형은 홈의 약점에 기록됩니다. ')+'다음 복습은 '+new Date(S.g[s.L.id].d).toLocaleDateString('ko-KR',{month:'long',day:'numeric'})+'입니다.'})}
    else{setupP(s);render(true)}break;
  case 'reset':if(armed){S=blank();save();armed=false;applySettings();FLASH='모든 기록을 지웠습니다.'}else armed=true;render();break;
  }});
function cardMove(d){const s=V.stack[V.stack.length-1];if(s&&s.type==='clesson'){const j=CLKEYS.indexOf(s.key)+d;if(j>=0&&j<CLKEYS.length){s.key=CLKEYS[j];render(true)}return}
  if(s&&s.type==='kanji'&&s.ids){const j=s.ids.indexOf(s.c)+d;if(j>=0&&j<s.ids.length){s.c=s.ids[j];render(true)}return}
  if(s&&s.type==='lesson'&&s.ids){const j=s.ids.indexOf(s.id)+d;if(j>=0&&j<s.ids.length){s.id=s.ids[j];render(true)}return}
  if(!s||s.type!=='cards')return;const i=s.i+d;if(i<0||i>=s.ids.length)return;s.i=i;s.flip=false;render(true)}
document.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT'||e.target.tagName==='TEXTAREA')return;if(e.key==='Enter'&&e.target.classList.contains('tk')){e.target.click();return}if(e.key==='ArrowLeft')cardMove(-1);else if(e.key==='ArrowRight')cardMove(1)});
let tx=null,ty=0;
document.addEventListener('touchstart',e=>{const t=e.touches[0];tx=t.clientX;ty=t.clientY},{passive:true});
document.addEventListener('touchend',e=>{if(tx===null)return;const t=e.changedTouches[0],dx=t.clientX-tx,dy=t.clientY-ty;tx=null;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)cardMove(dx<0?1:-1)},{passive:true});
const h0=location.hash.slice(1);if(h0==='book'){V.tab='vocab';V.vm='book'}else if(['home','vocab','kanji','grammar'].includes(h0))V.tab=h0;
applySettings();render();loadData();syncInit();try{speechSynthesis.onvoiceschanged=()=>{const t=V.stack[V.stack.length-1];if(t&&t.type==='settings')render()}}catch(e){}
